    ConfigurationItem.add_member(:related_events, Smithy::Schema::Shapes::ShapeRef.new(shape: RelatedEventList, location_name: 'relatedEvents', traits: {"smithy.api#documentation" => "<p>A list of CloudTrail event IDs.</p>\n         <p>A populated field indicates that the current configuration was\n\t\t\tinitiated by the events recorded in the CloudTrail log. For more\n\t\t\tinformation about CloudTrail, see <a href=\"https://docs.aws.amazon.com/awscloudtrail/latest/userguide/what_is_cloud_trail_top_level.html\">What Is CloudTrail</a>.</p>\n         <p>An empty field indicates that the current configuration was not\n\t\t\tinitiated by any event. As of Version 1.3, the relatedEvents field is empty. \n\t\t\tYou can access the <a href=\"https://docs.aws.amazon.com/awscloudtrail/latest/APIReference/API_LookupEvents.html\">LookupEvents API</a> in the <i>CloudTrail API Reference</i> to retrieve the events for the resource.</p>"}))
    ConfigurationItem.add_member(:relationships, Smithy::Schema::Shapes::ShapeRef.new(shape: RelationshipList, location_name: 'relationships', traits: {"smithy.api#documentation" => "<p>A list of related Amazon Web Services resources.</p>"}))
    ConfigurationItem.add_member(:configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: Configuration, location_name: 'configuration', traits: {"smithy.api#documentation" => "<p>A JSON-encoded string that contains the contents for the resource configuration. This string needs to be deserialized using <code>json.loads()</code> before you can access the contents.</p>"}))
    ConfigurationItem.add_member(:supplementary_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SupplementaryConfiguration, location_name: 'supplementaryConfiguration', traits: {"smithy.api#documentation" => "<p>A string to string map that contains additional contents for the resource configuration.Config returns this field for certain\n\t\t\tresource types to supplement the information returned for the\n\t\t\t<code>configuration</code> field.</p>\n         <p>This string to string map needs to be deserialized using <code>json.loads()</code> before you can accessing the contents.</p>"}))
    ConfigurationItem.add_member(:recording_frequency, Smithy::Schema::Shapes::ShapeRef.new(shape: RecordingFrequency, location_name: 'recordingFrequency', traits: {"smithy.api#documentation" => "<p>The recording frequency that Config uses to record configuration changes for the resource.</p>\n         <note>\n            <p>This field only appears in the API response when <code>DAILY</code> recording is enabled for a resource type.\n\t\t\t\tIf this field is not present, <code>CONTINUOUS</code> recording is enabled for that resource type. For more information on daily recording and continuous recording, see <a href=\"https://docs.aws.amazon.com/config/latest/developerguide/select-resources.html#select-resources-recording-frequency\">Recording Frequency</a> in the <i>Config\n\t\t\t\t\t\tDeveloper Guide</i>.</p>\n         </note>"}))
    ConfigurationItem.add_member(:configuration_item_delivery_time, Smithy::Schema::Shapes::ShapeRef.new(shape: ConfigurationItemDeliveryTime, location_name: 'configurationItemDeliveryTime', traits: {"smithy.api#documentation" => "<p>The time when configuration changes for the resource were delivered.</p>\n         <note>\n            <p>This field is optional and is not guaranteed to be present in a configuration item  (CI). If you are using daily recording,\n\t\t\tthis field will be populated. However, if you are using continuous recording,\n\t\t\tthis field will be omitted since the delivery time is instantaneous as the CI is available right away.</p>\n            <p>For more information on daily recording and continuous recording, see <a href=\"https://docs.aws.amazon.com/config/latest/developerguide/select-resources.html#select-resources-recording-frequency\">Recording Frequency</a> in the <i>Config\n\t\t\t\t\tDeveloper Guide</i>.</p>\n         </note>"}))
