    PutStoredQueryRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagsList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of <code>Tags</code> object.</p>"}))
