    SsmControls.add_member(:concurrent_execution_rate_percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: Percentage, location_name: 'ConcurrentExecutionRatePercentage', traits: {"smithy.api#documentation" => "<p>The maximum percentage of remediation actions allowed to run in parallel on the non-compliant resources for that specific rule. You can specify a percentage, such as 10%. The default value is 10. </p>"}))
    SsmControls.add_member(:error_percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: Percentage, location_name: 'ErrorPercentage', traits: {"smithy.api#documentation" => "<p>The percentage of errors that are allowed before SSM stops running automations on non-compliant resources for that specific rule.\n\t\t\tYou can specify a percentage of errors, for example 10%. If you do not specifiy a percentage, the default is 50%. \n\t\t\tFor example, if you set the ErrorPercentage to 40% for 10 non-compliant resources, then SSM stops running the automations when the fifth error is received. </p>"}))
